if (!defined('ABSPATH')) exit;
function idan_setup(){add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('custom-logo',array('height'=>130,'width'=>310,'flex-height'=>true,'flex-width'=>true));add_theme_support('html5',array('search-form','gallery','caption','style','script'));register_nav_menus(array('primary'=>'תפריט ראשי'));}add_action('after_setup_theme','idan_setup');
function idan_assets(){wp_enqueue_style('idan-rounded-font','https://fonts.googleapis.com/css2?family=Varela+Round&display=swap',array(),null);wp_enqueue_style('idan-style',get_stylesheet_uri(),array('idan-rounded-font'),'1.4.0');wp_enqueue_script('idan-menu',get_template_directory_uri().'/assets/menu.js',array(),'1.0.0',true);}add_action('wp_enqueue_scripts','idan_assets');
function idan_whatsapp(){return 'https://wa.me/972502850950?text='.rawurlencode('שלום, אשמח לקבל פרטים ולקבוע טיפול בעידן הבריאות');}
function idan_mascot(){ $id=absint(get_theme_mod('idan_mascot_image')); if($id){echo wp_get_attachment_image($id,'large',false,array('class'=>'mascot-actual','alt'=>'ד״ר צ׳אן יאמן – הדמות של עידן הבריאות'));}else{echo '<img class="mascot-actual" src="'.esc_url(get_template_directory_uri().'/assets/doctor-chan-original.png').'" alt="ד״ר צ׳אן יאמן – הדמות המקורית של עידן הבריאות" loading="eager">';}}
function idan_customize($wp_customize){$wp_customize->add_section('idan_mascot_section',array('title'=>'דמות ד״ר צ׳אן יאמן','priority'=>35));$wp_customize->add_setting('idan_mascot_image',array('sanitize_callback'=>'absint'));$wp_customize->add_control(new WP_Customize_Media_Control($wp_customize,'idan_mascot_image',array('label'=>'העלאת תמונת הדוקטור המקורית','section'=>'idan_mascot_section','mime_type'=>'image')));}add_action('customize_register','idan_customize');
function idan_seed_pages(){if(get_option('idan_seed_done'))return;$pages=array('home'=>array('בית',''), 'treatments'=>array('טיפולים','<h2>טיפול אישי המבוסס על הרפואה הסינית</h2><p>הטיפול מותאם לצרכיו של כל אדם לאחר תשאול והיכרות. בין השיטות שניתן לשלב בהתאם לצורך: דיקור סיני, מוקסה, כוסות רוח וטיפולי מגע.</p><h2>דיקור סיני</h2><p>שיטת טיפול מסורתית הכוללת החדרת מחטים דקות לנקודות מוגדרות בגוף. ניתן לשקול אותה כחלק מתוכנית טיפול מותאמת, לאחר בירור מצב בריאותי.</p><h2>מוקסה וכוסות רוח</h2><p>שיטות נוספות מעולם הרפואה הסינית, בהתאם להערכה המקצועית ולצרכי המטופל.</p>'), 'about'=>array('אודות','<h2>נעים להכיר, עידן שמואלי</h2><p>מטפל מוסמך ברפואה סינית. במרפאת עידן הבריאות אני מאמין בהקשבה, ביחס אישי ובהתאמת הטיפול לאדם שמולי.</p><p>כאן נוסיף את הסיפור המקצועי המלא והכשרות מאומתות מתוך החומרים המקוריים.</p>'), 'recommended-products'=>array('מוצרים מומלצים','<h2>מוצרים נבחרים</h2><p>כאן תמצאו מוצרים שאני בוחר להציג מהמותגים נוביקס ואקו סאפ. מומלץ לבדוק את המידע וההנחיות באתר היצרן.</p><p><strong>קוד קופון: idan10</strong></p><p><a href="https://noviks.co.il/">לאתר נוביקס</a> | <a href="https://ecosupp.co.il/">לאתר אקו סאפ</a></p><p>גילוי נאות: ייתכן שהשימוש בקוד ההנחה מקנה הטבה מסחרית למפרסם; יש לאמת ולציין את אופי הקשר.</p>'), 'contact'=>array('יצירת קשר','<h2>נשמח לשמוע מכם</h2><p>לתיאום טיפול או לשאלות אפשר לשלוח הודעה בוואטסאפ: <a href="https://wa.me/972502850950">050-2850950</a>.</p><p>כתובת המרפאה ושעות הפעילות יעודכנו לאחר אימות הפרטים.</p>'), 'blog'=>array('מאמרים וטיפים',''), 'privacy'=>array('מדיניות פרטיות','<p>עמוד זה דורש השלמה והתאמה לשירותים ולמידע הנאסף באתר לפני פרסום האתר. יש לפרט שימוש בעוגיות, טפסים, נתוני אנליטיקה ודרכי יצירת קשר.</p>'));
$ids=array();foreach($pages as $slug=>$data){$existing=get_page_by_path($slug);$ids[$slug]=$existing?$existing->ID:wp_insert_post(array('post_title'=>$data[0],'post_name'=>$slug,'post_content'=>$data[1],'post_type'=>'page','post_status'=>'publish'));}if(!is_wp_error($ids['home'])){update_option('show_on_front','page');update_option('page_on_front',$ids['home']);update_option('page_for_posts',$ids['blog']);}$menu=wp_create_nav_menu('תפריט עידן הבריאות');if(!is_wp_error($menu)){foreach(array('home','about','treatments','blog','recommended-products','contact') as $slug){wp_update_nav_menu_item($menu,0,array('menu-item-title'=>$pages[$slug][0],'menu-item-object'=>'page','menu-item-object-id'=>$ids[$slug],'menu-item-type'=>'post_type','menu-item-status'=>'publish'));}set_theme_mod('nav_menu_locations',array('primary'=>$menu));}update_option('idan_seed_done',1);}
add_action('after_switch_theme','idan_seed_pages');

// Default favicon until a custom WordPress Site Icon is set.
function idan_health_default_favicon() {
    if (!has_site_icon()) {
        echo '<link rel="icon" href="'.esc_url(get_template_directory_uri().'/assets/idan-health-icon.png').'" type="image/png">'."\n";
    }
}
add_action('wp_head', 'idan_health_default_favicon');

function idan_discount_catalog_setup(){
 $pg=get_page_by_path('discount-products');
 if(!$pg){$pid=wp_insert_post(array('post_title'=>'מוצרים בהנחה','post_name'=>'discount-products','post_type'=>'page','post_status'=>'publish','page_template'=>'page-discount-products.php'));}else{$pid=$pg->ID;if(get_page_template_slug($pid)!=='page-discount-products.php')update_post_meta($pid,'_wp_page_template','page-discount-products.php');}
 if(is_wp_error($pid)||!$pid)return;
 $loc=get_nav_menu_locations();if(!empty($loc['primary'])){$menu=$loc['primary'];$items=wp_get_nav_menu_items($menu);$found=false;foreach((array)$items as $item){if((int)$item->object_id===(int)$pid){$found=true;break;}}if(!$found)wp_update_nav_menu_item($menu,0,array('menu-item-title'=>'מוצרים בהנחה','menu-item-object'=>'page','menu-item-object-id'=>$pid,'menu-item-type'=>'post_type','menu-item-status'=>'publish'));}
}
add_action('init','idan_discount_catalog_setup');
